// Calls the Waipa District Council "Recycling Day Finder" IntraMaps API directly
// to get the next collection dates for both bins, instead of maintaining a
// yearly Postgres table by hand. Runs fresh every execution, so it's always
// up to date automatically.

const BASE = 'https://waipadc.spatial.t1cloud.com/spatial/IntraMaps/ApplicationEngine';
const CONFIG_ID = '6aa41407-1db8-44e1-8487-0b9a08965283';
const PROJECT_ID = 'b5bc138e-edce-4b01-b159-ec44539ab455';
const MODULE_ID = '5373c4e1-c975-4c8f-b51a-0ac976f5313c';
const SELECTION_LAYER = 'e7163a17-2f10-42b1-8dbf-8c53adf089a8';
const SEARCH_FORM_ID = 'e6677a33-9d47-407a-b199-5c7967a4be07';

// Change this to look up a different property - a street address works best
const ADDRESS = 'YOUR ADDRESS HERE';

const commonHeaders = {
  'Content-Type': 'application/json',
  'X-Requested-With': 'XMLHttpRequest',
  'Origin': 'https://waipadc.spatial.t1cloud.com',
  'Referer': `https://waipadc.spatial.t1cloud.com/spatial/IntraMaps/ApplicationEngine/frontend/mapbuilder/default.htm?configId=${CONFIG_ID}`,
};

// Step 1: start a session (session id comes back as a response header, not in the body)
const projectsResponse = await this.helpers.httpRequest({
  method: 'POST',
  url: `${BASE}/Projects/`,
  qs: {
    configId: CONFIG_ID,
    appType: 'MapBuilder',
    project: PROJECT_ID,
    datasetCode: '',
    includeDisabledModules: 'true',
  },
  headers: commonHeaders,
  returnFullResponse: true,
});
const session = projectsResponse.headers['x-intramaps-session'];
if (!session) {
  throw new Error('Did not receive an IntraMaps session header from the council API');
}

// Step 2: load the Recycling Day Finder module into this session
await this.helpers.httpRequest({
  method: 'POST',
  url: `${BASE}/Modules/`,
  qs: { IntraMapsSession: session },
  headers: commonHeaders,
  body: { module: MODULE_ID },
  json: true,
});

// Step 3: search for the address to find its mapKey/dbKey
const searchResponse = await this.helpers.httpRequest({
  method: 'POST',
  url: `${BASE}/Search/`,
  qs: {
    infoPanelWidth: 350,
    mode: 'Refresh',
    form: SEARCH_FORM_ID,
    resubmit: 'false',
    selectionLayersFilter: SELECTION_LAYER,
    IntraMapsSession: session,
  },
  headers: commonHeaders,
  body: { fields: [ADDRESS] },
  json: true,
});

const matches = searchResponse.fullText || [];
if (matches.length === 0) {
  throw new Error(`No property found matching "${ADDRESS}"`);
}
// If there's more than one match (e.g. "42" vs "42A"), this picks the first one -
// check match.displayValue below, or inspect matches[], if you need to disambiguate
const match = matches[0];

// Step 4: fetch the recycling info panel for that property
const refineResponse = await this.helpers.httpRequest({
  method: 'POST',
  url: `${BASE}/Search/Refine/Set`,
  qs: { IntraMapsSession: session },
  headers: commonHeaders,
  body: {
    selectionLayer: SELECTION_LAYER,
    mapKey: match.mapKey,
    infoPanelWidth: 350,
    mode: 'Refresh',
    dbKey: match.dbKey,
    zoomType: 'current',
  },
  json: true,
});

const fields = refineResponse.infoPanels.info1.feature.fields;
const getField = (caption) => {
  const field = fields.find((f) => f.caption === caption);
  return field ? field.value.value : null;
};

const months = { Jan: 0, Feb: 1, Mar: 2, Apr: 3, May: 4, Jun: 5, Jul: 6, Aug: 7, Sep: 8, Oct: 9, Nov: 10, Dec: 11 };
const parseNextDate = (text) => {
  const m = text && text.match(/(\d{1,2})-([A-Za-z]{3})-(\d{4})/);
  if (!m) return null;
  const [, day, mon, year] = m;
  return new Date(Number(year), months[mon], Number(day)).toISOString();
};

const propertyAddress = getField('Property Address');
const yellowText = getField('Mixed Recycling (YELLOW bin - Plastic 1 2 5, Paper, Cardboard, Cans):');
const blueText = getField('Glass Recycling (BLUE bin):');

return [
  { json: { Bin: 'Yellow', Date: parseNextDate(yellowText), Description: yellowText, Address: propertyAddress, MatchedDisplayValue: match.displayValue } },
  { json: { Bin: 'Blue', Date: parseNextDate(blueText), Description: blueText, Address: propertyAddress, MatchedDisplayValue: match.displayValue } },
];

// Input (from "Edit Fields", both formatted as dd-MM-yyyy strings):
// - RecycleDate
// - TodaysDate

function parseDDMMYYYY(str) {
  const [d, m, y] = str.split('-').map(Number);
  return new Date(y, m - 1, d);
}

const recycleLocal = parseDDMMYYYY($input.first().json.RecycleDate);
const todayLocal = parseDDMMYYYY($input.first().json.TodaysDate);

// Calculate the difference in whole days
const diffDays = Math.round((recycleLocal - todayLocal) / (1000 * 60 * 60 * 24));

// Return true if it's exactly 1 day before
return [
  {
    json: {
      isDayBefore: diffDays === 1,
      diffDays
    }
  }
];

